#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Signalbox owner setup: the clicks only Yannic can make (his identity, his
# payment, his accounts). Everything a secret touches goes straight from the
# browser or ~/Downloads into GitHub or EAS; nothing is printed, and only keys
# local dev needs go to .env. Agents do the rest from those secrets. Run one
# section at a time:
#
#   scripts/owner-setup/owner-setup.sh workos    # own sign-in keys (#35, #221), ~12 min
#   scripts/owner-setup/owner-setup.sh apple     # iOS distribution (#44), ~10 min after enrollment
#   scripts/owner-setup/owner-setup.sh android   # Android push (#44), ~6 min
#   scripts/owner-setup/owner-setup.sh expo      # CI builds through EAS (#44), ~1 min
#   scripts/owner-setup/owner-setup.sh kernel    # agents' real browsers (Kernel), ~1 min
#   scripts/owner-setup/owner-setup.sh typesafe  # Jev chat/task classifier, also into .env, ~1 min
#   scripts/owner-setup/owner-setup.sh boat      # Boat deployment key for Alchemy (#298), ~3 min
#
# See docs/operations/app-distribution.md and docs/operations/accounts-setup.md.

run_wizard() {

export GH_REPO="${GH_REPO:-JustYannicc/signalbox}"
local section="${1:-}" repo_root
repo_root="$(git rev-parse --show-toplevel)"
cd "$repo_root"

# wait_for_download GLOB prints the newest ~/Downloads file matching GLOB,
# waiting until one exists.
wait_for_download() {
  local file
  # shellcheck disable=SC2012,SC2086 # the glob is ours and file names are Apple's/Google's
  until file="$(ls -t "$HOME"/Downloads/$1 2>/dev/null | head -n1)" && [[ -n "$file" ]]; do
    warn "No ~/Downloads/$1 yet." >&2
    pause "Download it, then press Enter" >&2
  done
  printf '%s' "$file"
}

# secret_from_download NAME GLOB stores the newest matching download as a
# GitHub secret, then offers to delete the file once it's safely stored.
secret_from_download() {
  local name="$1" file
  file="$(wait_for_download "$2")"
  say "Found $(basename "$file")."
  set_secret "$name" "$(cat "$file")"
  [[ " ${WRITTEN_SECRET[*]} " == *" $name "* ]] || return 0
  note "GitHub can't show it again. Keep a copy in 1Password before deleting."
  if confirm "Delete $(basename "$file") from Downloads now?"; then rm -f "$file"; fi
}

# set_cloud_secret NAME VALUE sets NAME on both Signalbox Cloud GitHub environments.
set_cloud_secret() {
  local name="$1" value="$2" env
  for env in cloud-preview cloud-production; do
    if printf '%s' "$value" | gh secret set "$name" --env "$env" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$env/$name")
      printf '  %s✓ set%s %s on %s\n' "$GREEN" "$RESET" "$name" "$env"
    else
      SKIPPED+=("$env secret $name (gh secret set $name --env $env)")
      warn "couldn't set $name on $env; set it later"
    fi
  done
}

# ask_key_id KEY "Prompt" asks for an Apple Key ID: 10 uppercase letters and digits.
ask_key_id() {
  ask "$1" "$2"
  until [[ "${!1}" =~ ^[A-Z0-9]{10}$ ]]; do
    warn "Apple Key IDs are 10 letters and digits, like ABCDE12345."
    ask "$1" "$2"
  done
}

case "$section" in
workos)
TOTAL_STAGES=4
banner "Signalbox sign-in uses our own keys"

stage "WorkOS: find the provider redirect URIs"
say "All of this stays in the one WorkOS environment (SignalBox → Staging), so user ids don't change."
open_url "https://dashboard.workos.com/"
step "Top left: project SignalBox, environment Staging."
step "Authentication → OAuth providers. Keep this tab open: the next stages paste into it."
pause

stage "GitHub sign-in shows Signalbox instead of WorkOS Demo"
step "WorkOS tab: GitHub → Manage. Copy the Redirect URI."
open_url "https://github.com/settings/applications/new"
step "Application name: Signalbox"
step "Homepage URL: https://app.signalbox.run"
step "Authorization callback URL: the Redirect URI you copied. Leave device flow off."
step "Register application → Generate a new client secret."
step "WorkOS tab: Your app's credentials → paste Client ID and Client Secret → Save."
note "The secret goes from GitHub to WorkOS directly; nothing else needs it."
pause "Saved in WorkOS? Press Enter"

stage "Google sign-in shows Signalbox"
step "WorkOS tab: Google → Manage. Copy the Redirect URI."
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: signalbox → Create, and select it. (Android push reuses this project.)"
open_url "https://console.cloud.google.com/auth/branding"
step "Get started → App name: Signalbox, support email: yours → Audience: External → contact email → Create."
step "Branding → Authorized domains → add workos.com → Save. Skip the logo: it would need Google's brand review."
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application, name: WorkOS sign-in."
step "Authorized redirect URIs → Add URI → the Redirect URI from WorkOS → Create."
step "WorkOS tab: Your app's credentials → paste Client ID and Client secret → Save."
open_url "https://console.cloud.google.com/auth/audience"
step "Publish app → Confirm, or Google blocks everyone but test users."
pause "Saved in WorkOS and published? Press Enter"

stage "WorkOS: logo on the sign-in page"
say "Logos are the one WorkOS setting its API can't upload."
open -R "$repo_root/assets/prod/logo.svg" 2>/dev/null || true
step "WorkOS tab: Branding → Logo → upload assets/prod/logo.svg (Finder has it selected)."
step "Icon → upload assets/prod/black-universal-1024.png → Save."
pause
;;

apple)
TOTAL_STAGES=5
banner "Signalbox on iPhone through TestFlight"

stage "Apple Developer Program"
say "TestFlight, push notifications and Sign in with Apple all need the paid membership."
if ! confirm "Is your Apple Developer Program membership already active?"; then
  open_url "https://developer.apple.com/programs/enroll/"
  step "Enroll (individual or organization is your call) and pay."
  say "Apple usually approves within 48 hours. Re-run this section once the welcome email arrives."
  exit 0
fi
open_url "https://developer.apple.com/account#MembershipDetailsCard"
ask APPLE_TEAM_ID "Team ID (10 characters, under Membership details):"
set_var APPLE_TEAM_ID "$APPLE_TEAM_ID"

stage "App Store Connect API key for agents"
say "One Admin key lets agents register bundle ids, signing certificates, profiles, testers and"
say "TestFlight builds, and notarize desktop builds, without you."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "First time only: Request Access, accept, reload."
step "Team Keys → + → Name: Signalbox agents, Access: Admin → Generate."
step "Download API Key (Apple allows exactly one download)."
ask APPLE_API_ISSUER "Issuer ID (above the key list):"
ask_key_id APPLE_API_KEY_ID "Key ID of the new key:"
set_secret APPLE_API_ISSUER "$APPLE_API_ISSUER"
set_secret APPLE_API_KEY_ID "$APPLE_API_KEY_ID"
secret_from_download APPLE_API_KEY "AuthKey_${APPLE_API_KEY_ID}.p8"

stage "Push notification key"
note "The App Store Connect API can't create this one."
open_url "https://developer.apple.com/account/resources/authkeys/add"
step "Key Name: Signalbox push. Check Apple Push Notifications service (APNs) → Configure."
step "Environment: Sandbox & Production. Key Restriction: Team Scoped (All Topics) → Save."
step "Continue → Register → Download."
ask_key_id APNS_KEY_ID "Key ID of the push key:"
set_secret APNS_KEY_ID "$APNS_KEY_ID"
secret_from_download APNS_PRIVATE_KEY "AuthKey_${APNS_KEY_ID}.p8"

stage "App ID"
open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
step "App IDs → Continue → App → Continue."
step "Description: Signalbox. Bundle ID: Explicit, com.justyannicc.signalbox."
step "Leave capabilities alone (agents enable push, app groups and the rest) → Continue → Register."
pause

stage "App Store Connect app"
note "Apple's API can't create app records, so this form is yours."
open_url "https://appstoreconnect.apple.com/apps"
step "+ → New App → Platform: iOS."
step "Name: Signalbox (if taken, anything works for TestFlight; it can change before release)."
step "Primary language: English (U.S.). Bundle ID: com.justyannicc.signalbox. SKU: signalbox."
step "User Access: Full Access → Create."
pause "Created? Press Enter, then tell the coordinator Apple is done."
;;

android)
TOTAL_STAGES=2
banner "Signalbox push on Android"

stage "Firebase project and Android apps"
open_url "https://console.firebase.google.com/"
step "Create a project → choose the existing Google Cloud project signalbox → Analytics off."
step "Add app → Android → package com.justyannicc.signalbox → Register → skip the remaining steps."
step "Repeat for com.justyannicc.signalbox.preview and com.justyannicc.signalbox.dev."
step "Project settings → General → download google-services.json (after adding the last app)."
gsf="$(wait_for_download 'google-services*.json')"
say "Found $(basename "$gsf")."
if (cd apps/mobile && npx -y eas-cli@24 whoami >/dev/null 2>&1); then
  (cd apps/mobile && npx -y eas-cli@24 env:create --non-interactive --force \
    --name T3CODE_ANDROID_GOOGLE_SERVICES_FILE --type file --value "$gsf" --visibility secret \
    --environment production --environment preview --environment development >/dev/null) \
    && note "✓ set EAS file variable T3CODE_ANDROID_GOOGLE_SERVICES_FILE (all environments)" \
    || SKIPPED+=("EAS file variable T3CODE_ANDROID_GOOGLE_SERVICES_FILE from $gsf")
else
  SKIPPED+=("EAS file variable T3CODE_ANDROID_GOOGLE_SERVICES_FILE: run 'npx eas-cli login', then re-run this section")
fi

stage "Firebase sender key for the push relay"
step "Project settings → Service accounts → Generate new private key → Generate key."
warn "If Google says key creation is disabled by policy: IAM → Organization policies →"
note "  'Disable service account key creation' → Manage policy → Override → Off, for this project only."
secret_from_download FCM_SERVICE_ACCOUNT "signalbox*-firebase-adminsdk-*.json"
;;

expo)
TOTAL_STAGES=1
banner "EAS builds from CI"

stage "Expo access token"
open_url "https://expo.dev/accounts/justyannicc/settings/access-tokens"
step "Create token → Name: github-actions → Generate → copy."
ask_secret EXPO_TOKEN "Paste the token (hidden):"
set_secret EXPO_TOKEN "$EXPO_TOKEN"
;;

kernel)
TOTAL_STAGES=1
banner "Agents browse real sites through Kernel"

stage "Kernel API key"
open_url "https://dashboard.onkernel.com/api-keys"
step "Create an API key → copy it."
ask_secret KERNEL_API_KEY "Paste the Kernel API key (hidden):"
[[ -n "$KERNEL_API_KEY" ]] || { warn "No key entered."; exit 1; }
set_cloud_secret KERNEL_API_KEY "$KERNEL_API_KEY"
;;

typesafe)
TOTAL_STAGES=1
banner "Jev tells chats from tasks"

stage "TypeSafe API key"
say "The cloud reads it from both GitHub environments; local dev reads it from $ENV_FILE."
ask_secret TYPESAFE_API_KEY "Paste your Jev/TypeSafe API key (hidden):"
[[ -n "$TYPESAFE_API_KEY" ]] || { warn "No key entered."; exit 1; }
write_env TYPESAFE_API_KEY "$TYPESAFE_API_KEY"
set_cloud_secret TYPESAFE_API_KEY "$TYPESAFE_API_KEY"
;;

boat)
TOTAL_STAGES=2
banner "Boat deployment key for Alchemy (#298)"

stage "Create a deployment key"
open_url "https://boat.dev/dashboard"
step "Open the API Keys tab. Create a new key named signalbox-alchemy-deploy."
step "Use the admin preset and a 90-day expiry. Alchemy needs it to create a separate scoped runtime key as well as snapshots and environments."
say "The deployment key stays in CI. It is never bound into the app Worker or a VM."
say "Leave signalbox-cloud alone: it stays the runtime credential (BOAT_API_KEY)."
step "Copy the secret Boat shows once."
ask_secret BOAT_DEPLOY_API_KEY "Paste the new deployment key (hidden):"
[[ -n "$BOAT_DEPLOY_API_KEY" ]] || { warn "No key entered."; exit 1; }

stage "Store it for the preview and production plans"
say "This adds BOAT_DEPLOY_API_KEY to both GitHub environments. It doesn't deploy anything."
set_cloud_secret BOAT_DEPLOY_API_KEY "$BOAT_DEPLOY_API_KEY"
unset BOAT_DEPLOY_API_KEY
;;

*)
printf 'Usage: %s workos|apple|android|expo|kernel|typesafe|boat\n' "$0"
exit 1
;;
esac

finish
}

run_wizard "$@"; exit
